-- Generated by @forinda/kickjs-db v8.8.0 — review state lives in meta.json
-- Titles were not unique per workspace before: the oldest project keeps its
-- title, a later duplicate gets its id appended, so no row is lost.
UPDATE "projects" SET "title" = "title" || ' (' || "id" || ')'
WHERE EXISTS (
  SELECT 1 FROM "projects" AS "older"
  WHERE "older"."workspaceId" = "projects"."workspaceId"
    AND "older"."title" = "projects"."title"
    AND ("older"."createdAt" < "projects"."createdAt"
      OR ("older"."createdAt" = "projects"."createdAt" AND "older"."id" < "projects"."id"))
);
CREATE UNIQUE INDEX "projects_workspace_title_unique" ON "projects" ("workspaceId", "title");
